 "content": "from collections import Counter


def transform(grid):
    """Replace background cells between consecutive markers in each row/column."""
    counts = Counter(value for row in grid for value in row)
    background = counts.most_common(1)[0][0]
    marker = next(value for value in counts if value != background)
    out = [row[:] for row in grid]
    height, width = len(grid), len(grid[0])

    for r in range(height):
        positions = [c for c, value in enumerate(grid[r]) if value == marker]
        for left, right in zip(positions, positions[1:]):
            for c in range(left + 1, right):
                if grid[r][c] == background:
                    out[r][c] = 3

    for c in range(width):
        positions = [r for r in range(height) if grid[r][c] == marker]
        for top, bottom in zip(positions, positions[1:]):
            for r in range(top + 1, bottom):
                if grid[r][c] == background:
                    out[r][c] = 3
    return out


if __name__ == "__main__":
    demo_input = [
        [8, 8, 8, 6], [8, 8, 8, 6], [6, 8, 8, 8], [8, 8, 8, 8],
        [6, 8, 8, 6], [8, 8, 8, 6], [8, 6, 8, 8], [6, 8, 8, 8],
        [8, 6, 8, 8], [8, 6, 8, 8],
    ]
    demo_output = [
        [8, 8, 8, 6], [8, 8, 8, 6], [6, 8, 8, 3], [3, 8, 8, 3],
        [6, 3, 3, 6], [3, 8, 8, 6], [3, 6, 8, 8], [6, 3, 8, 8],
        [8, 6, 8, 8], [8, 6, 8, 8],
    ]
    assert transform(demo_input) == demo_output
    print("Demo verified")
